-- ข้อมูลตัวอย่าง ส่วนแรกได้จากฐานข้อมูลของเว็บหลังรัน npm run db:reset (01418321-final-project/db/seed)
-- ส่วนท้ายเพิ่มตัวอย่างให้ตารางประวัติที่ seed ของเว็บยังว่าง เพื่อใช้แสดงในตารางข้อมูลตัวอย่าง
-- เวลาเก็บเป็น UTC (+00)








-- ตั้ง reorder_no_seq ต่อจาก PO ล่าสุดในข้อมูลตั้งต้น (เหมือน db/seed ของเว็บ) PO ถัดไป = PO-0092
SELECT setval(
  'reorder_no_seq',
  COALESCE((
    SELECT MAX(substring(reorder_id FROM '^PO-([0-9]+)$')::bigint)
    FROM reorders
  ), 0) + 1,
  false
);
